package glitch

import data.glitch_lib

credential_keywords := {
    "username", "user", "account", "login", "principal", "identity", "admin", "root", "sa", "postgres", "mysql", "oracle",
    "password", "passwd", "pwd", "secret", "passphrase", "credential",
    "api_key", "apikey", "api_secret", "access_key", "secret_key", "token", "bearer", "jwt_secret", "auth_token",
    "private_key", "ssh_key", "cert", "certificate", "encryption_key", "decryption_key", "symmetric_key", "hmac_key", "salt"
}

default_password_patterns := {"default", "initial", "bootstrap", "setup", "changeme", "password", "123456", "admin"}

high_entropy_pattern := "^[A-Za-z0-9+/=]{20,}$|^[a-f0-9]{32,64}$"

is_credential_field(name) {
    lower_name := lower(name)
    keyword := credential_keywords[_]
    contains(lower_name, keyword)
}

is_static_credential_value(value) {
    value.ir_type == "String"
    count(value.value) > 0
    not is_external_reference(value.value)
    not is_variable_interpolation(value.value)
}

is_external_reference(str) {
    regex.match("(?i)(vault|secret_manager|kms|ssm|parameter_store|env|var\\.|data\\.|module\\.|lookup\\.|file\\()", str)
}

is_variable_interpolation(str) {
    regex.match("\\$\\{|\\{\\{|\\<\\%", str)
}

is_default_or_weak_password(str) {
    lower_str := lower(str)
    pattern := default_password_patterns[_]
    contains(lower_str, pattern)
}

is_high_entropy_string(str) {
    regex.match(high_entropy_pattern, str)
}

is_hardcoded_credential(attr) {
    is_credential_field(attr.name)
    is_static_credential_value(attr.value)
}

is_hardcoded_credential(attr) {
    is_credential_field(attr.name)
    attr.value.ir_type == "String"
    is_default_or_weak_password(attr.value.value)
}

is_hardcoded_credential(attr) {
    is_credential_field(attr.name)
    attr.value.ir_type == "String"
    is_high_entropy_string(attr.value.value)
}

check_nested_value(field_name, value) {
    is_credential_field(field_name)
    value.ir_type == "String"
    count(value.value) > 0
    not is_external_reference(value.value)
    not is_variable_interpolation(value.value)
}

check_nested_attr(attr) {
    attr.name == "connection_string"
    attr.value.ir_type == "String"
    regex.match("(?i)(password|pwd|pass)=", attr.value.value)
    not is_external_reference(attr.value.value)
