    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    walk(parent, [_, node])
    node.ir_type == "Variable"
    has_credential_context(node.name)
    node.value.ir_type == "String"
    is_credential_value(node.value)
    not is_credential_field(node.name)  # Avoid double counting
    result = {
        "type": "sec_hard_secr",
        "element": node,
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Credentials should not be hard-coded in Infrastructure as Code scripts. Use secure secret management instead. (CWE-798)"
    }
}

package glitch

import data.glitch_lib

import future.keywords.in

credential_keywords := {"password", "passwd", "pwd", "secret", "passphrase", "credential", "api_key", "apikey", "api_secret", "access_key", "secret_key", "token", "bearer", "jwt_secret", "auth_token", "private_key", "ssh_key", "encryption_key", "decryption_key", "symmetric_key", "hmac_key", "salt", "keystore_password", "truststore_password", "sha512_password"}

# Context keywords that suggest credential fields even if field name alone doesn't match
context_keywords := {"cvauth", "auth", "credential", "encrypt", "keystore", "truststore", "ssl", "tls", "login", "account"}

# Fields that are actual credentials when in context
context_credential_fields := {"key", "password", "secret", "token", "cert"}

is_credential_field(name) {
    lower_name := lower(name)
    keyword := credential_keywords[_]
    contains(lower_name, keyword)
}

# Check if parent context suggests this is a credential field
has_credential_context(path_str) {
    ctx := context_keywords[_]
    contains(lower(path_str), ctx)
}

is_external_reference(str) {
    regex.match("(?i)(vault|secret[_-]?manager|kms|ssm|parameter[_-]?store|env|lookup|file\\(|data\\.|module\\.|var\\.|keyvault|\\{\\{|\\$\\{|\\$\\()", str)
}

is_file_path(str) {
    regex.match("^(/[a-zA-Z0-9_.-]+)+\\.([a-zA-Z0-9]+)$", str)
}

is_ldap_dn(str) {
    regex.match("(?i)^[a-z]+=.+dc=.+$", str)
}

is_url(str) {
    regex.match("^(https?|ldaps?)://", str)
}

# Common non-credential values that might match patterns
is_common_config_value(str) {
    lower_str := lower(str)
    lower_str in {"localhost", "/sensu", "root", "administrator", "localhost', 'c:\\\\etc\\\\sensu', 'c:\\\\var\\\\log\\\\sensu", "/etc/sensu", "/var/log/sensu", "true", "false"}
}

# Check if value looks like a credential (non-empty string, not external ref, not placeholder, not common default)
is_credential_value(val) {
    val.ir_type == "String"
    count(val.value) > 0
    not is_external_reference(val.value)
    not is_file_path(val.value)
    not is_ldap_dn(val.value)
    not is_url(val.value)
    not is_common_config_value(val.value)
}

# Find all Hash nodes with their paths using walk
find_hash_with_path(node, path_prefix) = results {
    results = {p |
        walk(node, [path, val])
        val.ir_type == "Hash"
        p := {"node": val, "path": build_path_from_walk(path, path_prefix)}
    }
}

build_path_from_walk(path, prefix) = result {
    parts := [p |
        p := path[i]
        is_string(p)
    ]
    result := concat(".", array.concat([prefix | count(prefix) > 0], parts))
}

# Flatten nested Hash structure to find all key-value pairs at any depth
flatten_hash_entries(root_hash) = entries {
    entries = {e |
        walk(root_hash, [_, node])
        node.ir_type == "Hash"
        entry := node.value[_]
        entry.key.ir_type == "String"
        e := {"key": entry.key.value, "value": entry.value, "key_node": entry.key}
    }
}

# Check if entry is a credential in context
is_context_credential(entry, parent_path) {
    has_credential_context(parent_path)
    lower(entry.key) == context_credential_fields[_]
    is_credential_value(entry.value)
}

# Main detection: Variables with credential field names
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
