# Hash entries with direct credential field names
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    walk(parent, [_, node])
    node.ir_type == "Hash"
    entry := node.value[_]
    entry.key.ir_type == "String"
    is_credential_field(entry.key.value)
    is_credential_value(entry.value)
    result = {
        "type": "sec_hard_secr",
        "element": {
            "ir_type": "KeyValue",
            "name": entry.key.value,
            "value": entry.value,
            "line": entry.key.line,
            "column": entry.key.column,
            "end_line": entry.value.end_line,
            "end_column": entry.value.end_column
        },
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Credentials should not be hard-coded in Infrastructure as Code scripts. Use secure secret management instead. (CWE-798)"
    }
}

# Hash entries with credential fields in context (e.g., password inside cvauth)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    walk(parent, [path, node])
    node.ir_type == "Hash"
    # Get parent key from path
    count(path) > 0
    parent_key := path[count(path) - 1]
    is_string(parent_key)
    has_credential_context(parent_key)
    entry := node.value[_]
    entry.key.ir_type == "String"
    lower(entry.key.value) == context_credential_fields[_]
    is_credential_value(entry.value)
    result = {
        "type": "sec_hard_secr",
        "element": {
            "ir_type": "KeyValue",
            "name": entry.key.value,
            "value": entry.value,
            "line": entry.key.line,
            "column": entry.key.column,
            "end_line": entry.value.end_line,
            "end_column": entry.value.end_column
        },
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Credentials should not be hard-coded in Infrastructure as Code scripts. Use secure secret management instead. (CWE-798)"
    }
}
